#!/usr/bin/env sh
# fetch Consórcio PróUrbano / Ritmo (Ribeirão Mobilidade) — members Rápido D'Oeste + Transcorp, regulated by Transerp/RP Mobi (BR) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://raw.githubusercontent.com/jqueguiner/gtfs/main/synthesized/BR/ribeirao-preto/consorcio-prourbano-ritmo-ribeirao-mobilidade-me/gtfs/"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
